diff --git a/src/review.ts b/src/review.ts
--- /dev/null
+++ b/src/review.ts
@@ -0,0 +1,14 @@
+import type {ReviewResult} from "./types";
+
+export type ReviewIo = {
+    dispatch: () => Promise<string>;
+    // Parsing may dispatch once more on malformed output and replace the staged reply.
+    // The returned promise includes that paid retry, not just local decoding.
+    parse: (output: string) => Promise<ReviewResult>;
+};
+
+export const runReview = async (io: ReviewIo): Promise<ReviewResult> => {
+    const output = await io.dispatch();
+    // Allow one corrective model call if this reply does not satisfy the contract.
+    return io.parse(output);
+};
diff --git a/src/main.ts b/src/main.ts
--- a/src/main.ts
+++ b/src/main.ts
@@ -1,6 +1,7 @@
 import {parseWithRetry} from "./parse";
+import {runReview} from "./review";

-export const review = async (
+export const review = (
     callModel: (instruction: string) => Promise<string>,
     stage: (output: string) => void,
 ) => {
@@ -9,7 +10,9 @@
         stage(output);
         return output;
     };
-    const output = await dispatch("Return a JSON object with a findings string array.");
-    return parseWithRetry(output, () =>
-        dispatch("The reply was malformed. Return a JSON object with a findings string array."));
+    return runReview({
+        dispatch: () => dispatch("Return a JSON object with a findings string array."),
+        parse: (output) => parseWithRetry(output, () =>
+            dispatch("The reply was malformed. Return a JSON object with a findings string array.")),
+    });
 };
